using System;
using System.Collections.Generic;
using System.Linq;

public interface IDamageable
{
    int Health { get; }
    bool IsDestroyed { get; }
    void TakeDamage(int amount);
}

public class Crate : IDamageable
{
    public int Health { get; private set; }

    public Crate(int health) { Health = health; }

    public bool IsDestroyed => Health <= 0;

    public void TakeDamage(int amount) => Health = Math.Max(0, Health - amount);
}

public class ArmoredWall : IDamageable
{
    public int Health { get; private set; }
    public int Armor { get; }

    public ArmoredWall(int health, int armor)
    {
        Health = health;
        Armor = armor;
    }

    public bool IsDestroyed => Health <= 0;

    // Armor soaks up part of every hit; a small hit does nothing at all.
    public void TakeDamage(int amount) => Health = Math.Max(0, Health - Math.Max(0, amount - Armor));
}

public static class Combat
{
    public static int Explode(List<IDamageable> targets, int damage)
    {
        foreach (IDamageable t in targets) t.TakeDamage(damage);
        return targets.Count(t => t.IsDestroyed);
    }
}

