using System;
using System.Collections.Generic;
using System.Linq;

public class Score : IComparable<Score>
{
    public string Player { get; }
    public int Points { get; }
    public int Seconds { get; }

    public Score(string player, int points, int seconds)
    {
        Player = player;
        Points = points;
        Seconds = seconds;
    }

    // Negative: this one comes first. Positive: the other one does. 0: a tie.
    public int CompareTo(Score other)
    {
        if (other is null) return -1;
        int byPoints = other.Points.CompareTo(Points);   // reversed, so higher points come first
        if (byPoints != 0) return byPoints;
        return Seconds.CompareTo(other.Seconds);          // faster first
    }

    public override string ToString() => $"{Player} {Points}";
}

public static class Leaderboard
{
    public static List<string> Top(List<Score> scores, int n)
    {
        var copy = new List<Score>(scores);   // never surprise the caller by reordering their list
        copy.Sort();
        return copy.Take(n).Select(s => s.Player).ToList();
    }
}

