using System;
using System.Collections.Generic;
using System.Linq;

public interface INotifier
{
    List<string> Sent { get; }
    void Send(string to, string message);
}

public class SmsNotifier : INotifier
{
    public List<string> Sent { get; } = new();

    public void Send(string to, string message)
    {
        if (message.Length > 30) message = message.Substring(0, 30);   // SMS has little room
        Sent.Add($"SMS to {to}: {message}");
    }
}

public class EmailNotifier : INotifier
{
    public List<string> Sent { get; } = new();

    public void Send(string to, string message) => Sent.Add($"EMAIL to {to}: {message}");
}

public class StockAlert
{
    private readonly INotifier notifier;   // any notifier will do: SMS, email, or a fake in a test

    public StockAlert(INotifier notifier)
    {
        this.notifier = notifier;
    }

    public bool Check(string medicine, int count, int minimum, string contact)
    {
        if (count < 0) throw new ArgumentOutOfRangeException(nameof(count));
        if (count >= minimum) return false;
        notifier.Send(contact, $"Low stock: {medicine} ({count} left)");
        return true;
    }
}
